-- GENERADO por herramientas/generar-pistas-mapa.mjs desde herramientas/fuente/mapas-pistas.json (no editar).
-- Pistas para encontrar jefes escondidos o difíciles (qué hacer y dónde). Solo fuentes de WoW Forever.
-- [id de instancia] = { ["Nombre del jefe como en el mapa"] = { español, inglés, url de la fuente } }
WowFMapasPistas = {
  [33] = {
    ["Rethilgore"] = { "Está abajo, en la zona de las celdas (jail). Limpia antes a los worgen del piso de arriba para que no se unan a la pelea.", "He is down in the jail area. Clear the worgen on the floor above first so they don't join the fight.", "https://www.icy-veins.com/wow-forever/shadowfang-keep-guide" },
    ["Fel Steed"] = { "Son tres caballos en los establos (Stables), neutrales al principio. Si atacas a uno, vienen los tres: controla (CC) o separa a uno.", "Three horses in the Stables, neutral at first. Attacking one pulls all three: CC or off-tank one of them.", "https://www.icy-veins.com/wow-forever/shadowfang-keep-guide" },
    ["Commander Springvale"] = { "Está en el rincón izquierdo de una sala pequeña llena de enemigos: límpiala antes. Siempre viene con un Haunted Servitor y un Wailing Guardsman (mata primero al Guardsman).", "He is in the left corner of a small room full of adds: clear it first. He always pulls with a Haunted Servitor and a Wailing Guardsman (kill the Guardsman first).", "https://www.icy-veins.com/wow-forever/shadowfang-keep-guide" },
    ["Deathsworn Captain"] = { "Jefe raro: no sale siempre. Si aparece, está en el pasillo después de Odo the Blindwatcher y viene con dos paladines de esa zona.", "Rare spawn: not always there. When he spawns, he is in the corridor after Odo the Blindwatcher and pulls with two Paladin adds.", "https://www.icy-veins.com/wow-forever/shadowfang-keep-guide" },
    ["Wolf Master Nandos"] = { "Su sala tiene varios worgs: sácalos de uno en uno antes de atacar al jefe; durante la pelea llama más worgs.", "His room has several worgs: pull them one by one before the boss; he summons more worgs during the fight.", "https://www.icy-veins.com/wow-forever/shadowfang-keep-guide" },
  },
  [34] = {
    ["Bruegal Ironknuckle"] = { "Jefe raro: no sale en todas las visitas. Si está, viene rodeado de enemigos; límpialos primero.", "Rare spawn: not there every run. When he is, he is surrounded by adds; clear them first.", "https://www.icy-veins.com/wow-forever/the-stockade-guide" },
    ["Hamhock"] = { "Ve por el ala DERECHA de The Stockade: es uno de sus jefes del fondo y viene con dos Defias.", "Go down the RIGHT wing of The Stockade: he is one of its last bosses and pulls with two Defias.", "https://www.icy-veins.com/wow-forever/the-stockade-guide" },
    ["Bazil Thredd"] = { "Ve por el ala DERECHA: está solo en su sala, al fondo. Tiene más nivel que el resto de la mazmorra.", "Go down the RIGHT wing: he is alone in his room at the end. He is higher level than the rest of the dungeon.", "https://www.icy-veins.com/wow-forever/the-stockade-guide" },
    ["Dextren Ward"] = { "Ve por el ala IZQUIERDA hasta la última sala. Limpia antes las celdas de alrededor: su miedo (Intimidating Shout) te mete en ellas.", "Go down the LEFT wing to the last room. Clear the surrounding cells first: his fear (Intimidating Shout) runs you into them.", "https://www.icy-veins.com/wow-forever/the-stockade-guide" },
  },
  [36] = {
    ["Rhahk'Zor"] = { "Comparte sala con dos Defias Watchmen: dispárales de lejos y espéralos en el pasillo por el que llegaste; luego ve por el jefe.", "He shares his room with two Defias Watchmen: hit them at range and wait for them in the corridor you came from; then pull the boss.", "https://www.icy-veins.com/wow-forever/deadmines-guide" },
    ["Miner Johnson"] = { "Jefe raro: no sale siempre. Si está, va rodeado de Defias Miners (normales, mueren rápido).", "Rare spawn: not always there. When he is, he is surrounded by Defias Miners (non-elite, easy to kill).", "https://www.icy-veins.com/wow-forever/deadmines-guide" },
    ["Sneed"] = { "Empieza montado en su Shredder: limpia antes a los goblins de la sala (el Shredder da miedo en área). Al romper el Shredder, Sneed salta fuera.", "He starts inside his Shredder: clear the goblins in the room first (the Shredder has an AoE fear). When it breaks, Sneed jumps out.", "https://www.icy-veins.com/wow-forever/deadmines-guide" },
    ["Captain Greenskin"] = { "Patrulla la cubierta de arriba del barco Defias con un Defias Pirate y un Defias Squallshaper: espera a que pase y atácalos juntos.", "He patrols the upper deck of the Defias ship with a Defias Pirate and a Defias Squallshaper: wait for the patrol and pull them together.", "https://www.icy-veins.com/wow-forever/deadmines-guide" },
    ["Edwin VanCleef"] = { "Está en su camarote del barco. Al atacarlo salen dos Defias Blackguard escondidos, y otros dos cuando baja al 50 %.", "He is in his cabin on the ship. Pulling him also pulls two hidden Defias Blackguards, and two more come at 50% health.", "https://www.icy-veins.com/wow-forever/deadmines-guide" },
    ["Cookie"] = { "Está en la parte de atrás del barco Defias; suele ser el último. Llévalo lejos del barco y córtale Cookie's Cooking (se cura).", "He is on the back side of the Defias ship, usually the last pull. Kite him away from the ship and interrupt Cookie's Cooking (heal).", "https://www.icy-veins.com/wow-forever/deadmines-guide" },
  },
  [43] = {
    ["Kresh"] = { "Patrulla el agua del nivel de abajo de Wailing Caverns: búscalo nadando en esa zona.", "He patrols the water on the lower level of Wailing Caverns: look for him swimming there.", "https://www.icy-veins.com/wow-forever/wailing-caverns-guide" },
    ["Lord Cobrahn"] = { "Sigue el pasillo largo del lado OESTE hasta el final. Siempre viene con tres Deviate Pythons.", "Follow the long corridor on the WEST side to its end. He always pulls with three Deviate Pythons.", "https://www.icy-veins.com/wow-forever/wailing-caverns-guide" },
    ["Lord Pythas"] = { "Está en un cruce por donde patrullan Druids of the Fang y Deviate Shamblers: es fácil traer 1-2 de más; contrólalos (CC).", "He stands at an intersection where Druids of the Fang and Deviate Shamblers patrol: you may pull 1-2 extra; CC them.", "https://www.icy-veins.com/wow-forever/wailing-caverns-guide" },
    ["Deviate Faerie Dragon"] = { "Jefe raro: no sale siempre. Aparece en una zona con muchos enemigos; mata primero a los Druids of the Fang y córtales Sleep.", "Rare spawn: not always there. It appears in a busy area; kill the Druids of the Fang first and interrupt their Sleep.", "https://www.icy-veins.com/wow-forever/wailing-caverns-guide" },
    ["Mutanus the Devourer"] = { "No está al entrar: mata a los 4 líderes Druid of the Fang, vuelve a la entrada y habla con el Disciple of Naralex. Escóltalo al fondo; tras 2 oleadas sale Mutanus.", "Not there at first: kill the 4 Druid of the Fang leaders, go back to the entrance and talk to the Disciple of Naralex. Escort him; Mutanus comes after 2 waves.", "https://www.icy-veins.com/wow-forever/wailing-caverns-guide" },
  },
  [48] = {
    ["Ghamoo-ra"] = { "Está en el centro de una isla, en la SEGUNDA masa grande de agua.", "He is in the middle of an island in the SECOND large body of water.", "https://www.icy-veins.com/wow-forever/blackfathom-deeps-guide" },
    ["Lady Sarevess"] = { "Escondida en una cueva BAJO el agua, al suroeste de Ghamoo-ra: bucea hasta ella. Viene con dos patrullas naga; límpialas antes.", "Hidden in an UNDERWATER cave southwest of Ghamoo-ra: dive to reach her. She pulls with two naga patrols; clear them first.", "https://www.icy-veins.com/wow-forever/blackfathom-deeps-guide" },
    ["Gelihast"] = { "Pasa el tercer pasillo largo lleno de naga y sátiros: está en una sala de murlocs. Los murlocs huyen con poca vida; atráelos hacia atrás.", "Go past the third long corridor full of naga and satyrs: he is in a murloc room. Murlocs flee at low health; pull them back.", "https://www.icy-veins.com/wow-forever/blackfathom-deeps-guide" },
    ["Lorgus Jett"] = { "Patrulla el pasillo después de Gelihast: espera a que pase solo para no traer naga o sátiros de más.", "He patrols the corridor after Gelihast: wait until he walks by alone so you don't pull extra naga or satyrs.", "https://www.icy-veins.com/wow-forever/blackfathom-deeps-guide" },
    ["Old Serra'kis"] = { "Jefe escondido muy al fondo del agua, DEBAJO del santuario del Twilight's Hammer. Baja buceando; lleva Unending Breath o Water Breathing Potion.", "Hidden boss deep underwater, BELOW the Twilight's Hammer sanctum. Dive down; bring Unending Breath or a Water Breathing Potion.", "https://www.icy-veins.com/wow-forever/blackfathom-deeps-guide" },
    ["Twilight Lord Kelris"] = { "Dentro del santuario del Twilight's Hammer. Usa la pared de la entrada para atraer a sus guardias de uno en uno antes de ir por él.", "Inside the Twilight's Hammer sanctum. Use the wall at the entrance to line-of-sight pull his guards before him.", "https://www.icy-veins.com/wow-forever/blackfathom-deeps-guide" },
    ["Aku'mai"] = { "Para abrir su puerta, tras Kelris enciende los 4 braseros alrededor del brasero gigante, UNO A UNO: cada uno saca una oleada.", "To open his door, after Kelris light the 4 braziers around the giant brazier ONE AT A TIME: each one spawns a wave.", "https://www.icy-veins.com/wow-forever/blackfathom-deeps-guide" },
    ["Lorgalis Manuscript"] = { "Objeto de la misión Knowledge in the Deeps (Alliance): recógelo aquí y llévalo a Gerrig Bonegrip, en el Forlorn Cavern de Ironforge.", "Item for the quest Knowledge in the Deeps (Alliance): pick it up here and bring it to Gerrig Bonegrip in the Forlorn Cavern, Ironforge.", "https://www.wowhead.com/forever/quest=971" },
    ["Argent Guard Thaelrid"] = { "NPC amistoso DENTRO de la mazmorra: habla con él para coger Blackfathom Villainy (matar a Twilight Lord Kelris).", "Friendly NPC INSIDE the dungeon: talk to him to get Blackfathom Villainy (kill Twilight Lord Kelris).", "https://www.wowhead.com/forever/quest=1200" },
  },
  [389] = {
    ["Taragaman the Hungerer"] = { "Está en la cámara central, rodeada de lava. Pelea con él lejos del borde: su empujón tira al tanque a la lava.", "He is in the central chamber, surrounded by lava. Tank him away from the edge: his knockback throws the tank into the lava.", "https://www.icy-veins.com/wow-forever/ragefire-chasm-guide" },
    ["Bazzalan"] = { "En la misma sala que Jergosh the Invoker, pero SUBIENDO por una rampa. Viene con dos acompañantes.", "In the same room as Jergosh the Invoker, but UP a ramp. He pulls with two adds.", "https://www.icy-veins.com/wow-forever/ragefire-chasm-guide" },
  },
  [2998] = {
    ["Saltspine"] = { "Está en un lago dentro de la mazmorra: búscalo en el agua.", "He is in a lake inside the dungeon: look for him in the water.", "https://www.icy-veins.com/wow-forever/excavation-site-wetlands-guide" },
    ["Shadetooth"] = { "Limpia la guarida de cocodrilos para llegar a él y pelea ahí. Hay raptors en sigilo entre los arbustos de alrededor: mátalos antes.", "Clear the crocodile den to reach him and fight there. Stealthed raptors hide in the bushes around him: kill them first.", "https://www.icy-veins.com/wow-forever/excavation-site-wetlands-guide" },
    ["Relic Guardian"] = { "Empieza inactivo: para despertarlo, usa el Archival Panel que está a su DERECHA.", "He starts inactive: to start the fight, interact with the Archival Panel to his RIGHT.", "https://www.icy-veins.com/wow-forever/excavation-site-wetlands-guide" },
  },
  [2999] = {
    ["Witherfang"] = { "Patrulla cerca de la entrada, por King's Alley, con varios Broodlings: revisa bien antes de avanzar para que no te sorprenda.", "She patrols near the entrance, by King's Alley, with several Broodlings: look around before moving so she doesn't jump you.", "https://www.icy-veins.com/wow-forever/ruins-of-lordaeron-guide" },
    ["The Baron"] = { "Al final de un pasillo, en la parte SURESTE de la mazmorra.", "At the end of a hallway in the SOUTHEAST part of the dungeon.", "https://www.icy-veins.com/wow-forever/ruins-of-lordaeron-guide" },
    ["Viktor the Vile"] = { "No está al llegar: en las ruinas de una casa del SUROESTE, usa la Grim Campfire de la chimenea. Salen oleadas de esqueletos y luego él.", "Not there at first: in the ruined house in the SOUTHWEST, use the Grim Campfire in the fireplace. Skeleton waves come, then him.", "https://www.icy-veins.com/wow-forever/ruins-of-lordaeron-guide" },
    ["The Abandoned"] = { "No está al llegar: en el OESTE, sigue el pasillo hasta la estatua de ojos rojos brillantes y acércate. Salen 3 oleadas y luego el jefe.", "Not there at first: in the WEST, follow the corridor to the statue with glowing red eyes and walk up to it. 3 waves come, then the boss.", "https://www.icy-veins.com/wow-forever/ruins-of-lordaeron-guide" },
    ["Bjork"] = { "Al final de un pasillo, en la parte NOROESTE de la mazmorra.", "At the end of a corridor in the NORTHWEST part of the dungeon.", "https://www.icy-veins.com/wow-forever/ruins-of-lordaeron-guide" },
    ["Rath'mael"] = { "En el centro: se ve desde casi toda la mazmorra, pero hay que dar un rodeo para llegar a su zona. Mata a los de alrededor para empezar.", "In the center: visible from most of the dungeon, but you must go around to reach his area. Kill the mobs around him to engage.", "https://www.icy-veins.com/wow-forever/ruins-of-lordaeron-guide" },
    ["Lordaeron Captain"] = { "Raro: puede salir en el OESTE solo tras matar a todos los demás jefes. Es amistoso para Alliance: solo la Horde puede matarlo. Patrulla un camino largo.", "Rare: may spawn in the WEST only after all other bosses die. Friendly to Alliance: only Horde can kill him. Long patrol route.", "https://www.icy-veins.com/wow-forever/ruins-of-lordaeron-guide" },
  },
  [3065] = {
    ["Faldrim Anvilmar"] = { "Patrulla la zona de Anvilmar's Rest: limpia un par de Enraged Apparition antes de atacarlo.", "He patrols the Anvilmar's Rest area: clear a couple of Enraged Apparitions before pulling him.", "https://www.icy-veins.com/wow-forever/hall-of-thanes-guide" },
    ["Plunder"] = { "Patrulla la sala antes del último jefe. Llévalo a la sala anterior para que su empujón no te tire sobre otros enemigos.", "He patrols the room before the last boss. Bring him to the previous room so his knockback doesn't throw you into other mobs.", "https://www.icy-veins.com/wow-forever/hall-of-thanes-guide" },
    ["Durgen Dirgehammer"] = { "Último jefe, con dos Lesser Stone Golems. Limpia antes a los Dark Iron de los bordes de su sala y mata los golems primero.", "Final boss, with two Lesser Stone Golems. Clear the Dark Iron mobs around the room first and kill the golems before him.", "https://www.icy-veins.com/wow-forever/hall-of-thanes-guide" },
  },
}
